// Draft a sprite. TWO RULES for the prompt, TWO BACKENDS for the drawing.
//
// THE RULES (unchanged, and using the wrong one produces a confidently wrong
// picture):
//
// DAEMONS (kind: "creature", the default) follow 9.4: NEUTRAL GREYS with a few
// saturated accents, coloured at build time from the type ramp -- "the art
// stays type-agnostic, so one drawing is correct whatever the type is."
// gbasprite.py reads body from accent BY SATURATION, so a colourful creature
// is not merely off-style, it is unusable.
//
// PEOPLE (kind: "character" | "overworld") follow 9.4's other half, settled
// 2026-09-06 by generating four treatments and looking at them. The Clears are
// coloured by FAMILY, not type -- Crystal is a golden fox. Three clauses, each
// one a treatment that failed:
//   1. Animality INTEGRATED, never grafted. Never an animal head on a human
//      body; C proved that is a mask no colour-matching repairs.
//   2. Drawn PLAINLY. No fur or scale texture, no gloss, no musculature, no
//      fluff. The clause that separates fable from furry; A got it wrong.
//   3. Head-to-body ratio carries AGE. Unstated, everyone comes out cute,
//      which nearly broke Scorn.
//
// THE BACKENDS:
//
//   backend: "local" (default)  the Bonsai model on this network. Free,
//                               private, ~18s, and text-to-image only.
//   backend: "openrouter"       a hosted image model. Costs a fraction of a
//                               cent, and crucially does IMG2IMG.
//
// img2img is the reason this parameter exists rather than a second endpoint.
// A back view generated independently DRIFTS from its front -- DEADLOCK's
// paired only because it is a featureless round mass, and anything with
// asymmetry or markings would not have. Passing the front as `baseline` asks
// for the same creature from another angle instead of a similar one.
//
// Either way this returns a 384px illustration. A real overworld frame is
// 16x32 and a sheet is 144x32 for nine of them: REFERENCE TO DRAW FROM.
const req = $input.first().json, headers = req.headers || {}, body = req.body || {};
const expected = $env.DEX_SHARED_SECRET;
if (expected && headers['x-dex-secret'] !== expected) throw new Error('Unauthorized: bad or missing x-dex-secret');

const kind = String(body.kind || 'creature').toLowerCase();
if (!['creature', 'character', 'overworld'].includes(kind)) {
  throw new Error(`Unknown kind '${kind}'. Use creature, character or overworld.`);
}
const backend = String(body.backend || 'local').toLowerCase();
if (!['local', 'openrouter'].includes(backend)) {
  throw new Error(`Unknown backend '${backend}'. Use local or openrouter.`);
}

const name = String(body.name || (kind === 'creature' ? 'creature' : 'person'));
const idea = String(body.idea || '');
let prompt;

if (kind === 'creature') {
  const accent = String(body.accent || '');
  prompt = [
    `pixel art sprite of ${name}${idea ? ', ' + idea : ''}`,
    `drawn in NEUTRAL GREYS only -- light grey, mid grey, dark grey, near-black outline`,
    accent ? `with a single small ${accent} as the only colour` : `with no colour anywhere`,
    `front-facing, centred, full body, thick near-black outline, flat shading, no gradients`,
    `plain white background, no text, no border, no shadow on the ground`,
  ].join(', ');
} else {
  const species = String(body.species || 'fox');
  const wearing = String(body.wearing || '');
  const age = String(body.age || 'adult').toLowerCase();
  const ratio = (age === 'child' || age === 'young')
    ? 'child proportions, large head relative to the body'
    : 'adult proportions, small head relative to the body';
  const framing = kind === 'overworld'
    ? 'overworld game sprite, standing and facing the viewer straight on, full body, feet visible, symmetrical stance'
    : 'full body character reference, facing the viewer, relaxed stance';
  prompt = [
    `${ratio} ${species} character named ${name}${idea ? ', ' + idea : ''}`,
    wearing ? `wearing ${wearing}` : '',
    `funny-animal fable style in the tradition of Carl Barks, Disney's Robin Hood and Redwall`,
    `animality INTEGRATED not grafted: ${species} head proportioned to the body, paw hands, a tail`,
    `NOT an animal head on a human body, NOT a mask, NOT a costume`,
    `drawn PLAINLY: flat colour, cel shading, thick dark outline`,
    `NO fur texture, NO scale texture, no gloss, no highlights, no musculature, no fluff`,
    framing,
    `plain white background, no text, no border`,
  ].filter(Boolean).join(', ');
}

// A baseline turns "draw this" into "draw THIS ONE, from here". Only the
// hosted backend can use it; saying so is better than ignoring it silently.
const baseline = typeof body.baseline === 'string' && body.baseline.length > 100 ? body.baseline : null;
if (baseline && backend !== 'openrouter') {
  throw new Error('baseline requires backend "openrouter" -- the local model is text-to-image only.');
}
if (baseline) {
  prompt = `Redraw the creature in the supplied image, keeping its EXACT shape, proportions and markings. `
         + `Change only the viewpoint and pose. ${prompt}`;
}

// gemini-3.1-flash-lite-image is the default: cheapest of the eleven, and this
// is a DRAFTING endpoint. Override with `model` when a draft is worth more.
const orModel = String(body.model || 'google/gemini-3.1-flash-lite-image');

const content = [{ type: 'text', text: prompt }];
if (baseline) {
  content.push({ type: 'image_url', image_url: { url: `data:image/png;base64,${baseline}` } });
}

return [{
  json: {
    kind,
    backend,
    model: backend === 'openrouter' ? orModel : 'bonsai-local',
    usedBaseline: Boolean(baseline),
    bonsaiBody: { prompt, steps: 4, guidance: 1.0, width: 384, height: 384 },
    orBody: { model: orModel, modalities: ['image', 'text'], messages: [{ role: 'user', content }] },
  },
}];

// Both backends land here, and they return the drawing differently: Bonsai
// hands back raw PNG bytes, OpenRouter a data URI inside a chat completion.
// Normalising here means the caller sees one shape whichever drew it.
//
// `kind`, `backend` and `model` are echoed. A caller that cannot tell WHICH
// rule and WHICH model produced a sprite cannot tell a correct one from a
// wrong one, because both look deliberate -- that is the whole reason these
// parameters exist.
const meta = $('Validate + Build Prompt').first().json || {};
let spriteBase64 = null;

if (meta.backend === 'openrouter') {
  const r = $input.first().json || {};
  const msg = ((r.choices || [])[0] || {}).message || {};
  const img = (msg.images || [])[0];
  const url = img && (img.image_url ? img.image_url.url : img.url);
  if (typeof url === 'string') {
    const comma = url.indexOf(',');
    spriteBase64 = comma >= 0 ? url.slice(comma + 1) : url;
  }
} else {
  try {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
    if (buf && buf.length) spriteBase64 = buf.toString('base64');
  } catch (e) { /* generation failed -> the caller gets a null and a reason */ }
}

return [{
  json: {
    kind: meta.kind || null,
    backend: meta.backend || null,
    model: meta.model || null,
    usedBaseline: Boolean(meta.usedBaseline),
    spriteBase64,
    spriteMime: spriteBase64 ? 'image/png' : null,
    error: spriteBase64 ? null : 'generation_failed',
  },
}];
